-- Load seed data for schema 'banking'.
-- Run from this folder after creating the schema:  psql -d yourdb -f load_banking.sql
\set ON_ERROR_STOP on
BEGIN;
SET search_path TO banking;

-- Identity columns are GENERATED ALWAYS; allow explicit ids while loading.
DO $$ DECLARE r record; BEGIN
  FOR r IN SELECT table_name, column_name FROM information_schema.columns
           WHERE table_schema = 'banking' AND is_identity = 'YES' AND identity_generation = 'ALWAYS' LOOP
    EXECUTE format('ALTER TABLE banking.%I ALTER COLUMN %I SET GENERATED BY DEFAULT', r.table_name, r.column_name);
  END LOOP; END $$;

\copy currencies (currency_code, name, minor_units) FROM 'currencies.csv' WITH (FORMAT csv, HEADER true)
\copy exchange_rates (base_currency, quote_currency, rate, effective_at) FROM 'exchange_rates.csv' WITH (FORMAT csv, HEADER true)
\copy branches (branch_id, branch_code, name, address, city, country, phone, opened_on, is_active) FROM 'branches.csv' WITH (FORMAT csv, HEADER true)
\copy employees (employee_id, branch_id, employee_code, full_name, role, email, is_active) FROM 'employees.csv' WITH (FORMAT csv, HEADER true)
\copy customers (customer_id, customer_number, customer_type, first_name, last_name, date_of_birth, national_id_hash, legal_name, registration_no, email, phone, kyc_status, risk_rating, home_branch_id, created_at, updated_at) FROM 'customers.csv' WITH (FORMAT csv, HEADER true)
\copy customer_addresses (address_id, customer_id, address_type, line1, line2, city, state, postal_code, country, valid_from, valid_to) FROM 'customer_addresses.csv' WITH (FORMAT csv, HEADER true)
\copy kyc_documents (document_id, customer_id, document_type, document_number_hash, issuing_country, issued_on, expires_on, storage_uri, status, verified_by, verified_at) FROM 'kyc_documents.csv' WITH (FORMAT csv, HEADER true)
\copy account_products (product_id, product_code, name, category, currency_code, interest_rate, minimum_balance, monthly_fee, overdraft_limit, is_active) FROM 'account_products.csv' WITH (FORMAT csv, HEADER true)
\copy accounts (account_id, account_number, product_id, branch_id, currency_code, status, ledger_balance, available_balance, opened_at, closed_at, last_activity_at, version, updated_at) FROM 'accounts.csv' WITH (FORMAT csv, HEADER true)
\copy account_holders (account_id, customer_id, role, added_at) FROM 'account_holders.csv' WITH (FORMAT csv, HEADER true)
\copy transactions (transaction_id, reference, transaction_type, channel, description, status, initiated_by, idempotency_key, value_date, created_at, posted_at, reversal_of) FROM 'transactions.csv' WITH (FORMAT csv, HEADER true)
\copy ledger_entries (entry_id, transaction_id, account_id, direction, amount, currency_code, balance_after, created_at) FROM 'ledger_entries.csv' WITH (FORMAT csv, HEADER true)
\copy payees (payee_id, customer_id, nickname, payee_name, bank_name, bank_code, account_number, currency_code, is_verified, created_at) FROM 'payees.csv' WITH (FORMAT csv, HEADER true)
\copy transfers (transfer_id, from_account_id, to_account_id, payee_id, amount, currency_code, fx_rate, fee_amount, rail, status, transaction_id, memo, scheduled_for, created_at, completed_at, failure_reason) FROM 'transfers.csv' WITH (FORMAT csv, HEADER true)
\copy standing_orders (standing_order_id, from_account_id, payee_id, amount, frequency, next_run_date, end_date, is_active) FROM 'standing_orders.csv' WITH (FORMAT csv, HEADER true)
\copy cards (card_id, account_id, customer_id, card_type, network, pan_token, last4, expiry_month, expiry_year, status, daily_limit, credit_limit, issued_at) FROM 'cards.csv' WITH (FORMAT csv, HEADER true)
\copy card_authorizations (authorization_id, card_id, merchant_name, merchant_category_code, amount, currency_code, approved, decline_reason, transaction_id, authorized_at) FROM 'card_authorizations.csv' WITH (FORMAT csv, HEADER true)
\copy loans (loan_id, loan_number, customer_id, loan_account_id, disbursement_account_id, loan_type, principal, interest_rate, term_months, status, collateral_description, officer_id, applied_at, approved_at, disbursed_at, maturity_date, updated_at) FROM 'loans.csv' WITH (FORMAT csv, HEADER true)
\copy loan_schedule (loan_id, installment_no, due_date, principal_due, interest_due, principal_paid, interest_paid, penalty_amount, paid_on) FROM 'loan_schedule.csv' WITH (FORMAT csv, HEADER true)
\copy aml_alerts (alert_id, customer_id, transaction_id, rule_code, score, status, assigned_to, created_at, resolved_at) FROM 'aml_alerts.csv' WITH (FORMAT csv, HEADER true)
\copy audit_log (audit_id, actor_type, actor_id, action, entity, entity_id, old_values, new_values, ip_address, occurred_at) FROM 'audit_log.csv' WITH (FORMAT csv, HEADER true)

-- Restore GENERATED ALWAYS and move sequences past the loaded ids.
DO $$ DECLARE r record; BEGIN
  FOR r IN SELECT table_name, column_name FROM information_schema.columns
           WHERE table_schema = 'banking' AND is_identity = 'YES' LOOP
    EXECUTE format('SELECT setval(pg_get_serial_sequence(''banking.%I'', %L), COALESCE((SELECT max(%I) FROM banking.%I), 0) + 1, false)',
                   r.table_name, r.column_name, r.column_name, r.table_name);
    EXECUTE format('ALTER TABLE banking.%I ALTER COLUMN %I SET GENERATED ALWAYS', r.table_name, r.column_name);
  END LOOP; END $$;

COMMIT;
